<?php require_once '../config/config.php';require_login();$title='Share a Recipe';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$fs=['title','description','cuisine','dietary_preference','difficulty','ingredients','instructions','cooking_tips','image','video_url'];foreach($fs as $f)$$f=trim($_POST[$f]??'');$prep=(int)$_POST['prep_time'];$cook=(int)$_POST['cook_time'];$serv=(int)$_POST['servings'];if($image&&!filter_var($image,FILTER_VALIDATE_URL)){$image='';}if($video_url!==''&&!youtube_id($video_url)){$video_url='';}if(!$title||!$description||!$ingredients||!$instructions)flash('danger','Complete the required fields.');else{$s=db()->prepare("INSERT INTO recipes(title,description,cuisine,dietary_preference,difficulty,prep_time,cook_time,servings,ingredients,instructions,cooking_tips,image,video_url,author_id,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)");$s->execute([$title,$description,$cuisine,$dietary_preference,$difficulty,$prep,$cook,$serv,$ingredients,$instructions,$cooking_tips,$image!==''?$image:null,$video_url!==''?$video_url:null,user()['id'],'pending']);flash('success','Recipe submitted for review.');header('Location:../dashboard.php');exit;}}require '../includes/header.php';?><div class="page-hero"><div class="container"><span class="eyebrow">Community Cookbook</span><h1 class="fw-bold">Share your recipe</h1></div></div><section class="section"><div class="container"><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="col-md-8"><label class="form-label">Recipe title *</label><input class="form-control" name="title" required></div><div class="col-md-4"><label class="form-label">Cuisine</label><input class="form-control" name="cuisine"></div><div class="col-md-8"><label class="form-label">Image URL</label><input class="form-control" type="url" name="image" placeholder="https://example.com/photo.jpg"><div class="form-text">Optional. Leave blank to use a placeholder image.</div></div><div class="col-md-4"><label class="form-label">YouTube video URL</label><input class="form-control" type="url" name="video_url" placeholder="https://www.youtube.com/watch?v=..."><div class="form-text">Optional. Shown with your ingredients.</div></div><div class="col-12"><label class="form-label">Description *</label><textarea class="form-control" name="description" required></textarea></div><div class="col-md-4"><label class="form-label">Diet</label><select class="form-select" name="dietary_preference"><?php foreach(['General','Vegetarian','Vegan','Gluten-Free','Dairy-Free','Low-Carb','High-Protein','Halal'] as $x):?><option><?=$x?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Difficulty</label><select class="form-select" name="difficulty"><option>Easy</option><option>Medium</option><option>Hard</option></select></div><div class="col-md-4"><label class="form-label">Servings</label><input class="form-control" type="number" name="servings" value="4"></div><div class="col-md-6"><label class="form-label">Prep minutes</label><input class="form-control" type="number" name="prep_time" value="15"></div><div class="col-md-6"><label class="form-label">Cook minutes</label><input class="form-control" type="number" name="cook_time" value="30"></div><div class="col-md-6"><label class="form-label">Ingredients *</label><textarea class="form-control" name="ingredients" rows="9" required></textarea></div><div class="col-md-6"><label class="form-label">Instructions *</label><textarea class="form-control" name="instructions" rows="9" required></textarea></div><div class="col-12"><label class="form-label">Cooking tips</label><textarea class="form-control" name="cooking_tips" rows="4"></textarea></div><button class="btn btn-primary">Submit for review</button></form></div></section><?php require '../includes/footer.php';?>